 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    source = next(((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2), None)
    if source is None:
        return out
    r, c = source
    if r == 0: dr, dc = 1, 0
    elif r == h - 1: dr, dc = -1, 0
    elif c == 0: dr, dc = 0, 1
    else: dr, dc = 0, -1

    # Each beam advances straight until it meets a wall. It then follows
    # the wall's near edge; at either end it can pass through an opening.
    q = deque([(r, c, dr, dc)])
    seen = set()
    while q:
        r, c, dr, dc = q.popleft()
        while True:
            state = (r, c, dr, dc)
            if state in seen:
                break
            seen.add(state)
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if grid[nr][nc] != 8:
                r, c = nr, nc
                if grid[r][c] == 0:
                    out[r][c] = 2
                continue

            # A wall is aligned with the direction of travel. Follow its
            # contiguous segment along the perpendicular neighboring lane.
            if dc:
                wr, wc = nr, nc
                lo = hi = wr
                while lo > 0 and grid[lo - 1][wc] == 8: lo -= 1
                while hi + 1 < h and grid[hi + 1][wc] == 8: hi += 1
                lane_c = wc - dc
                for rr in range(max(0, lo - 1), min(h - 1, hi + 1) + 1):
                    if grid[rr][lane_c] == 0:
                        out[rr][lane_c] = 2
                ends = (lo - 1, hi + 1)
                for rr in ends:
                    if 0 <= rr < h and grid[rr][wc] == 0:
                        q.append((rr, lane_c, dr, dc))
            else:
                wr, wc = nr, nc
                lo = hi = wc
                while lo > 0 and grid[wr][lo - 1] == 8: lo -= 1
                while hi + 1 < w and grid[wr][hi + 1] == 8: hi += 1
                lane_r = wr - dr
                for cc in range(max(0, lo - 1), min(w - 1, hi + 1) + 1):
                    if grid[lane_r][cc] == 0:
                        out[lane_r][cc] = 2
                ends = (lo - 1, hi + 1)
                for cc in ends:
                    if 0 <= cc < w and grid[wr][cc] == 0:
                        q.append((lane_r, cc, dr, dc))
            break
    return out
